func scoreTone(score int) (tone, label string) {
	switch {
	case score >= 90:
		return "red", "Hot"
	case score >= 70:
		return "brand", "Strong"
	case score >= 50:
		return "amber", "Medium"
	default:
		return "gray", "Low"
	}
}

