func initialsOf(name string) string {
	rs := []rune(name)
	if len(rs) == 0 {
		return "?"
	}
	// take first letter of up to two words
	var out []rune
	space := true
	for _, r := range rs {
		if space && r != ' ' {
			out = append(out, r)
			if len(out) == 2 {
				break
			}
		}
		space = r == ' ' || r == '.' || r == '-'
	}
	if len(out) == 0 {
		return string(rs[0])
	}
	return string(out)
}

